{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Brivaracetam, the closest retrieved analogue by Morgan similarity, has almost 100% absolute oral bioavailability in humans; its shared pyrrolidine/propyl framework and amide functionality support a high-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Peramivir has <3% oral bioavailability, but this is driven by a highly polar guanidine/carboxylate zwitterion that the query lacks, so this low-F evidence is only weakly transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "Perindoprilat has about 19% oral bioavailability in young subjects, just below the threshold, but its low F is associated with two free carboxylates; the query has no free acid, limiting transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Perindopril, the ethyl ester prodrug of perindoprilat, has about 75% oral bioavailability, showing that masking polar acidic groups yields high F; the query similarly lacks free acidic groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Methysergide has 13% oral bioavailability, but its low systemic availability is tied to ergoline first-pass metabolism, a scaffold not present in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Ergometrine, an amide-containing alkaloid with polar hydroxyl groups, shows oral bioavailability between 34% and 117%, supporting that amide/polyhydroxylated molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Metformin has 50–60% oral bioavailability despite very high polarity, showing that polar small molecules can be orally bioavailable, although its absorption relies on transporters not clearly relevant to the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) because the closest analogue brivaracetam has near-complete oral bioavailability, the query passes Lipinski-like physicochemical limits, and the low-F analogues owe their poor F to ionizable acids/guanidine or ergoline first-pass metabolism that are absent in the query; however, low Morgan similarities and the unusual thioglucoside moiety add uncertainty.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.23), limiting transferability.",
    "No evidence addresses the intestinal permeability, efflux, or first-pass metabolism of the specific thioglucoside/pyrrolidine scaffold.",
    "Human absolute oral bioavailability data for a close glycosylated analogue are lacking."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

